  // ---------- 2. injection + sensitive-data screen (N04) ----------
  function collectStrings(obj, path = '', out = []) {
    if (typeof obj === 'string') out.push({ path, value: obj });
    else if (Array.isArray(obj)) obj.forEach((v, i) => collectStrings(v, `${path}[${i}]`, out));
