  // ---------- 4. deterministic lookups + reference levels (N11) ----------
  const TI_ORDER = ['CLEAN', 'UNKNOWN', 'SUSPICIOUS_OR_CONFLICTING', 'MALICIOUS_MEDIUM', 'MALICIOUS_HIGH'];
  function lookupTI(entities, ti) {
