  // ---------- 10. HITL decision authorisation (WF-2) ----------
  const DECIDABLE = ['PENDING_CLOSURE_CONFIRMATION', 'PENDING_ANALYST_REVIEW', 'ESCALATED_PENDING_APPROVAL', 'EXCEPTION_MANUAL_QUEUE', 'ESCALATED_TO_LEAD'];
