        const mal = recs.filter((r) => r.reputation === 'MALICIOUS');
        if (mal.some((r) => r.confidence >= 0.8)) bump('MALICIOUS_HIGH');
        else if (mal.length) bump('MALICIOUS_MEDIUM');
