        proposed_classification: S.en(CLASS_ORDER),
        incident_category: S.en(['FALSE_POSITIVE', 'BENIGN_TRUE_POSITIVE', 'SUSPICIOUS_NEEDS_REVIEW', 'CONFIRMED_INCIDENT_LIKELY']),
