  // ---------- 8. scoring engine (N17) ----------
  const agentIndicatesInjection = (o) => !!(o && typeof o.escalation_reason === 'string' && /injection/i.test(o.escalation_reason));
  function score(ctx, cfg) {
    const W = cfg.weights;
