      case 'boolean': if (typeof v !== 'boolean') errs.push(`${at}: expected boolean`); break;
      case 'enum': if (!spec.values.includes(v)) errs.push(`${at}: '${v}' not in [${spec.values.join(', ')}]`); break;
      case 'array':
