        if (v.length < spec.min || v.length > spec.max) errs.push(`${at}: expected ${spec.min}-${spec.max} items, got ${v.length}`);
        v.forEach((x, i) => checkSchema(x, spec.items, `${at}[${i}]`, errs)); break;
